package io.github.diodeme.ji.storage.sqlite;

import java.sql.Connection;
import java.sql.SQLException;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/** Read-only SQLite schema projection used for exact legacy classification. */
public final class SqliteSchema {
    private SqliteSchema() {}

    public static Map<String, Set<String>> tables(Connection connection) throws SQLException {
        var result = new LinkedHashMap<String, Set<String>>();
        try (var statement = connection.prepareStatement("""
                SELECT name FROM sqlite_master
                WHERE type = 'table' AND name NOT LIKE 'sqlite_%'
                ORDER BY name
                """); var rows = statement.executeQuery()) {
            while (rows.next()) {
                String table = rows.getString(1);
                var columns = new LinkedHashSet<String>();
                try (var columnStatement = connection.createStatement();
                     var columnRows = columnStatement.executeQuery("PRAGMA table_info(" + quote(table) + ")")) {
                    while (columnRows.next()) columns.add(columnRows.getString("name"));
                }
                result.put(table, Set.copyOf(columns));
            }
        }
        return Map.copyOf(result);
    }

    public static boolean empty(Connection connection) throws SQLException {
        return tables(connection).isEmpty();
    }

    private static String quote(String identifier) {
        return '"' + identifier.replace("\"", "\"\"") + '"';
    }
}
